package com.notdroid.notnews

import com.google.gson.GsonBuilder
import com.notdroid.notnews.db.newsApi.NewsApiResponse
import okhttp3.OkHttpClient
import okhttp3.Request
import org.junit.Test

import org.junit.Assert.*
import java.io.File

/**
 * Example local unit test, which will execute on the development machine (host).
 *
 * See [testing documentation](http://d.android.com/tools/testing).
 */
class SimpleUnitTest {
  //example one
  @Test
  fun gsonShouldWorks() {
    val everything =
      File(File(".").absoluteFile.parentFile?:File("."),"api-response.json").reader()

    val notError=GsonBuilder().setPrettyPrinting().create().fromJson(everything, NewsApiResponse::class.java)
    
    assertNotNull(notError.totalResults)
    assertEquals(264,notError.totalResults?:0)
  }
  
  @Test
  fun testBase64Image(){
    val response = OkHttpClient().newCall(Request.Builder().addHeader("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:145.0) Gecko/20100101 Firefox/145.0").url("https://www.gstatic.com/images/branding/searchlogo/ico/favicon.ico").build()).execute()
    
    val base64Image = makeBase64Image(response.body()?.bytes()!!, response.header("content-type")
      ?: "image/png")
    assertEquals(base64Image,"""data:image/x-icon;base64,""")
  }
  
  
  
  
}